style.css:
@-moz-document domain("discord.com") {
/* Wallpaper */
html, body, #app-mount {
  background: url("https://i.pinimg.com/1200x/2d/2e/6a/2d2e6ab6722011601d9ee597fe51c80c.jpg") center/cover fixed !important;
}

/* Make app transparent */
#app-mount {
  background: transparent !important;
}

/* Panels (WITHOUT backdrop-filter to avoid errors) */
[class*="chatContent"],
[class*="sidebar"],
[class*="membersWrap"],
[class*="container"] {
  background: rgba(15, 15, 20, 0.65) !important;
  border-radius: 12px;
}

/* Input box */
[class*="channelTextArea"] {
  background: rgba(255,255,255,0.08) !important;
  border-radius: 10px;
}

/* Remove black overlays */
[class*="bg"] {
  background: transparent !important;
}
}
